INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34811, 'Revelation 16:2', 'Revelation', 16, 2, 'نو لومړۍ فرښته لاړه او خپل جام یې په ځمکه باندې توی کړ او د هغو خلکو په بدنونو باندې چې د ځناور نښې یې درلودلې او د هغه مجسمې ته یې عبادت کاوه، خطرناکه او دردناکه زخمونه راښکاره شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_2.mp3', '', 1761754199, 1761754199),
(34812, 'Revelation 16:3', 'Revelation', 16, 3, 'دوهمې فرښتې خپل جام په بحر کې توی کړ او د بحر اوبه د مړي د وینې په شان شوې او د بحر ټول ژوندي موجودات مړه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_3.mp3', '', 1761754199, 1761754199),
(34813, 'Revelation 16:4', 'Revelation', 16, 4, 'درېمې فرښتې خپل جام په سیندونو او په چینو کې توی کړ او د هغو اوبه په وینو باندې بدلې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_4.mp3', '', 1761754199, 1761754199),
(34814, 'Revelation 16:5', 'Revelation', 16, 5, 'بیا ما واورېدل چې هغې فرښتې چې په اوبو باندې یې واک او اختیار درلود، وویل: ای سپېڅلی خدایه! چې ته یې او وې ته یې عادل ځکه تا کړي دا قضاوتونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_5.mp3', '', 1761754199, 1761754199),
(34815, 'Revelation 16:6', 'Revelation', 16, 6, 'ځکه تویې کړې هغوی وینې ستا د سپېڅلو خلکو او پیغمبرانو څښلو دپاره دې هغوی ته ورکړې وینې ځکه لایق وو هغوی د دې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_6.mp3', '', 1761754199, 1761754199),
(34816, 'Revelation 16:7', 'Revelation', 16, 7, 'ما د قربانۍ د ځای نه یو اواز واورېد چې ویل یې: ای څښتنه، مطلق قادره خدایه عادلانه او رښتیني دي ستا قضاوتونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_7.mp3', '', 1761754199, 1761754199),
(34817, 'Revelation 16:8', 'Revelation', 16, 8, 'څلورمې فرښتې خپل جام په لمر باندې توی کړ او لمر ته اجازه ورکړل شوه چې په خپل اور باندې خلک وسوځوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_8.mp3', '', 1761754199, 1761754199),
(34818, 'Revelation 16:9', 'Revelation', 16, 9, 'هغوی د هغې سختې ګرمۍ له امله وسوځېدل او د خدای نوم ته یې چې په دې بلاګانو باندې یې واک او اختیار درلود، کفر وویل. هغوی د خپلو ګناهونو څخه توبه ونه ویستله او د خدای ثنا یې ونه ویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_9.mp3', '', 1761754199, 1761754199),
(34819, 'Revelation 16:10', 'Revelation', 16, 10, 'پنځمې فرښتې خپل جام د هغه ځناور په تخت باندې توی کړ او د هغه پاچاهي په تیاره کې ډوبه شوه. خلکو د درد له امله خپل غاښونه چیچل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_10.mp3', '', 1761754199, 1761754199),
(34820, 'Revelation 16:11', 'Revelation', 16, 11, 'او د اسمان خدای ته به یې د خپلو دردونو او زخمونو له امله کفر ویل، خو د خپلو بدو کارونو څخه یې توبه نه ویستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_11.mp3', '', 1761754199, 1761754199),
(34821, 'Revelation 16:12', 'Revelation', 16, 12, 'شپږمې فرښتې خپل جام د فرات په لوی سیند کې توی کړ او د سیند اوبه وچې شوې، ترڅو د ختیځ د پاچاهانو د راتللو دپاره لاره تیاره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_12.mp3', '', 1761754199, 1761754199),
(34822, 'Revelation 16:13', 'Revelation', 16, 13, 'بیا ما ولیدل چې د ښامار د خولې نه، د هغه ځناور د خولې نه او د هغه جعلي پیغمبر د خولې نه د چونګښو په شان درې پېریان راووتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_13.mp3', '', 1761754199, 1761754199),
(34823, 'Revelation 16:14', 'Revelation', 16, 14, 'دا شیطاني روحونه دي چې معجزې ښایي. هغوی د ټولې نړۍ پاچاهانو ته ورځي چې هغوی سره راټول کړي چې د لوی قضاوت په ورځ د مطلق قادر خدای په وړاندې وجنګیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_14.mp3', '', 1761754199, 1761754199),
(34824, 'Revelation 16:15', 'Revelation', 16, 15, 'څښتن وایي: «ګورئ، زه به لکه د غله په شان درشم. بختور دی هغه څوک چې بېداره وي، خپل کالي یې اغوستي وي، ترڅو هغه د خلکو په مخکې لوڅ ونه ګرځي او ونه شرمیږي!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_15.mp3', '', 1761754199, 1761754199),
(34825, 'Revelation 16:16', 'Revelation', 16, 16, 'نو هغو پېریانو پاچاهان په هغه ځای کې سره راټول کړل چې په عبرانۍ کې ورته «ارمګدون» وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_16.mp3', '', 1761754199, 1761754199),
(34826, 'Revelation 16:17', 'Revelation', 16, 17, 'بیا اوومې فرښتې خپل جام په هوا کې توی کړ او د خدای په کور کې د تخت نه یو لوړ اواز راغی چې ویل یې: «هرڅه پای ته ورسېدل!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_17.mp3', '', 1761754199, 1761754199),
(34827, 'Revelation 16:18', 'Revelation', 16, 18, 'وروسته بیا برېښنا وپړکېدله او د تندرغږ او غړمبار شو او یوه داسې سخته زلزله وشوه چې د انسان د پیدایښت راهیسې کله نه وه شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_18.mp3', '', 1761754199, 1761754199),
(34828, 'Revelation 16:19', 'Revelation', 16, 19, 'هغه لوی ښار درې ټوټې شو او د نړۍ ټول ښارونه وران شول. خدای ته لوی بابل ور په یاد شو او هغه یې مجبور کړ چې هغه پیاله وڅښي چې د هغه د ډېر قهر او غضب د شرابو نه ډکه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_19.mp3', '', 1761754199, 1761754199),
(34829, 'Revelation 16:20', 'Revelation', 16, 20, 'ټولې جزیرې له نظره پناه او ورکې شوې او غرونه له منځه لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_20.mp3', '', 1761754199, 1761754199),
(34830, 'Revelation 16:21', 'Revelation', 16, 21, 'د اسمان نه د انسانانو په سرونو باندې ډېره غټه ږلۍ چې پنځه څلوېښت کیلوګرامه وزن یې درلود، راوورېدله او خلکو د دې ږلۍ له امله خدای ته کفر ویل، ځکه چې دا ډېر سخت افت ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation16_verse_21.mp3', '', 1761754199, 1761754199),
(34831, 'Revelation 21:1', 'Revelation', 21, 1, 'بیا ما یو نوی اسمان او نوې ځمکه ولیدله، ځکه چې لومړنی اسمان او لومړنۍ ځمکه ورک شول او بحر نور نه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_1.mp3', '', 1761754199, 1761754199),
(34832, 'Revelation 21:2', 'Revelation', 21, 2, 'ما سپېڅلی ښار یعنې نوی اورشلیم ولیده چې د خدای له خوا د اسمان نه راښکته کېده او داسې تیار کړای شوی ؤ لکه چې ناوې د خپل مېړه دپاره سینګار شوې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_2.mp3', '', 1761754199, 1761754199),
(34833, 'Revelation 21:3', 'Revelation', 21, 3, 'ما د تخت نه یو لوړ اواز واورېد چې ویل یې: «ګورئ، اوس د خدای د اوسېدلو ځای د خلکو په منځ کې دی. خدای به د هغوی سره اوسیږي. هغوی به د هغه قوم وي او هغه په خپله به د هغوی په منځ کې د هغوی خدای وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_3.mp3', '', 1761754199, 1761754199),
(34834, 'Revelation 21:4', 'Revelation', 21, 4, 'خدای به د هغوی د سترګو ټولې اوښکې وچې کړي. نور به مرګ، ویر، ژړا او درد نه وي، ځکه چې پخواني شیان تېر شوي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_4.mp3', '', 1761754199, 1761754199),
(34835, 'Revelation 21:5', 'Revelation', 21, 5, 'هغه کس چې په تخت ناست ؤ، ویې ویل: «ګورئ، زه ټول شیان نوي کوم.» همدارنګه هغه راته وویل: «دا ولیکه، ځکه چې دا خبرې د باور وړ او رښتیا دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_5.mp3', '', 1761754199, 1761754199),
(34836, 'Revelation 21:6', 'Revelation', 21, 6, 'او بیا یې ماته وویل: «دا وشول! زه الف او یا، پیل او پای یم. هرڅوک چې تږی وي زه به هغه ته د چینې څخه د ژوندون اوبه په وړیا توګه ورکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_6.mp3', '', 1761754199, 1761754199),
(34837, 'Revelation 21:7', 'Revelation', 21, 7, 'څوک چې بریالی شي، هغه به د دې ټولو برکتونو وارث شي. زه به د هغه خدای یم او هغه به زما اولاد وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_7.mp3', '', 1761754199, 1761754199),
(34838, 'Revelation 21:8', 'Revelation', 21, 8, 'خو د وېرېدونکو، بې‌ایمانانو، فاسدانو، قاتلانو، زناکارانو، جادوګرانو، بت‌پرستانو او ټولو دروغجنو خلکو ځای به د اور په بحیره او سوځېدونکو ګوګړو کې وي. دا دوهم مرګ دی.» نوی اورشلیم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_8.mp3', '', 1761754199, 1761754199),
(34839, 'Revelation 21:9', 'Revelation', 21, 9, 'بیا د هغو اوو فرښتو څخه یوه فرښته چې د اوو بلاګانو نه ډک جامونه ورسره وو، ماته راغله او ویې ویل: «راشه، زه به تاته ناوې یعنې د وري ښځه دروښایم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_9.mp3', '', 1761754199, 1761754199),
(34840, 'Revelation 21:10', 'Revelation', 21, 10, 'بیا کله چې زه د روح القدس تر اغېزې لاندې وم، فرښتې زه د یو ډېر لوړ غره څوکې ته بوتلم او د اورشلیم سپېڅلی ښار یې چې د خدای له خوا د اسمان څخه راښکته کېده، راته وښوده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_10.mp3', '', 1761754199, 1761754199),
(34841, 'Revelation 21:11', 'Revelation', 21, 11, 'دا ښار د خدای په جلال روښانه ؤ. هغه د قیمتي تیږو په شان ځلېده او د لعل او بلور په شان صفا ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_11.mp3', '', 1761754199, 1761754199),
(34842, 'Revelation 21:12', 'Revelation', 21, 12, 'دې ښار لوی او لوړ دېوالونه درلودل او دولس دروازې یې لرلې او په هره دروازه کې یې فرښته ولاړه وه. په دروازو باندې د اسراییلو د قوم د دولسو قبیلو نومونه لیکل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_12.mp3', '', 1761754199, 1761754199),
(34843, 'Revelation 21:13', 'Revelation', 21, 13, 'درې دروازې د ختیځ خواته، درې د شمال خواته، درې د جنوب خواته او درې دروازې د لوېدیځ خواته وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_13.mp3', '', 1761754199, 1761754199),
(34844, 'Revelation 21:14', 'Revelation', 21, 14, 'د ښار دېوال په دولسو بنیادونو باندې جوړ شوی ؤ او په هغو باندې د وري د دولسو رسولانو نومونه لیکل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_14.mp3', '', 1761754199, 1761754199),
(34845, 'Revelation 21:15', 'Revelation', 21, 15, 'کومې فرښتې چې زما سره خبرې کولې د هغې په لاس کې د سرو زرو یو متر ؤ چې د ښار او د هغه د دروازو او دېوالونو اندازه ورباندې معلومه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_15.mp3', '', 1761754199, 1761754199),
(34846, 'Revelation 21:16', 'Revelation', 21, 16, 'ښار د مربع په شکل جوړ شوی ؤ چې اوږدوالی او پلنوالی یې یوشان ؤ او فرښتې د هغه متر په وسیله دا ښار اندازه کړ چې دولس زره ستادیا ؤ. د هغه اوږدوالی، پلنوالی او لوړوالی یو برابر ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_16.mp3', '', 1761754199, 1761754199),
(34847, 'Revelation 21:17', 'Revelation', 21, 17, 'بیا هغې دېوالونه اندازه کړل چې یو سل او څلور څلوېښت کیوبټ لوړوالی یې درلود چې دا د انساني معیار له مخې ؤ چې فرښتې ورڅخه هم کار اخیسته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_17.mp3', '', 1761754199, 1761754199),
(34848, 'Revelation 21:18', 'Revelation', 21, 18, 'دېوال د لعلونو څخه جوړ شوی ؤ په داسې حال کې چې خپله ښار د سوچه سرو زرو نه جوړ شوی ؤ او د ښیښې په شان صفا ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_18.mp3', '', 1761754199, 1761754199),
(34849, 'Revelation 21:19', 'Revelation', 21, 19, 'د ښار د دېوالونو بنیادونه په ډول ډول قیمتي تیږو باندې سینګار کړای شوي وو. لومړنی بنیاد د لعلونو، دوهم د لاجوردو، درېم د سپینو عقیقو، څلورم د زمردو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_19.mp3', '', 1761754199, 1761754199),
(34850, 'Revelation 21:20', 'Revelation', 21, 20, 'پنځم د سرو عقیقو، شپږم د جیګري عقیقو، اووم د زبرجدو، اتم د شینچکي یاقوتو، نهم د زیړو یاقوتو، لسم د شنو عقیقو، یوولسم د فېروزې او دولسم د بانجاني یاقوتو څخه جوړ شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_20.mp3', '', 1761754199, 1761754199),
(34851, 'Revelation 21:21', 'Revelation', 21, 21, 'هغه دولس دروازې دولس مرغلرې وې، یعنې هره دروازه د یوې مرغلرې څخه جوړه شوې وه. د ښار لوی سرک د سوچه سرو زرو او د ښیښې په شان صفا ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_21.mp3', '', 1761754199, 1761754199),
(34852, 'Revelation 21:22', 'Revelation', 21, 22, 'ما په ښار کې د خدای کور ونه لیده، ځکه چې مطلق قادر څښتن خدای او وری خپله د دې ښار د خدای کور دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_22.mp3', '', 1761754199, 1761754199),
(34853, 'Revelation 21:23', 'Revelation', 21, 23, 'هغه ښار د لمر یا د سپوږمۍ رڼا ته اړتیا نه لري، ځکه چې د خدای جلال هغه روښانه کوي او وری د هغه څراغ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_23.mp3', '', 1761754199, 1761754199),
(34854, 'Revelation 21:24', 'Revelation', 21, 24, 'د هغه په رڼا کې به قومونه ګرځي او د نړۍ پاچاهان به د خپل شان او شوکت سره هغه ته ورننوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_24.mp3', '', 1761754199, 1761754199),
(34855, 'Revelation 21:25', 'Revelation', 21, 25, 'د ښار دروازې د ورځې له خوا هېڅکله نه بندیږي او هلته به هېڅ شپه نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_25.mp3', '', 1761754199, 1761754199),
(34856, 'Revelation 21:26', 'Revelation', 21, 26, 'هغوی به د قومونو شان او شوکت او عزت دې ښار ته راوړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_26.mp3', '', 1761754199, 1761754199),
(34857, 'Revelation 21:27', 'Revelation', 21, 27, 'خو هېڅ ناپاکه شیان به دې ښار ته ورننوتلی نه شي او نه به هغه څوک چې د کرکې وړ کارونه کوي او نه دروغجن خلک. یوازې هغه کسان به هغه ښار ته ورننوځي چې نومونه یې د وري د ژوندون په کتاب کې لیکل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation21_verse_27.mp3', '', 1761754199, 1761754199),
(34858, 'John 2:1', 'John', 2, 1, 'دوه ورځې وروسته د جلیل د قانا په ښار کې واده ؤ او د عیسی مور هم هلته وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_1.mp3', '', 1761754199, 1761754199),
(34859, 'John 2:2', 'John', 2, 2, 'عیسی او د هغه شاګردانو ته هم واده ته بلنه ورکړل شوې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_2.mp3', '', 1761754199, 1761754199),
(34860, 'John 2:3', 'John', 2, 3, 'کله چې د واده د مېلمنو سره شراب خلاص شول نو د عیسی مور عیسی ته وویل: «د هغوی سره نور شراب نشته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_3.mp3', '', 1761754199, 1761754199),
(34861, 'John 2:4', 'John', 2, 4, 'عیسی ځواب ورکړ: «مورې! په دې کې زما او ستا څه کار دی؟ زما وخت لا نه دی رارسېدلی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_4.mp3', '', 1761754199, 1761754199),
(34862, 'John 2:5', 'John', 2, 5, 'د عیسی مور د هغه ځای نوکرانو ته وویل: «هرڅه چې عیسی درته ووایي هغه وکړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_5.mp3', '', 1761754199, 1761754199),
(34863, 'John 2:6', 'John', 2, 6, 'په هغه ځای کې شپږ لوی د تیږې منګي ایښي وو چې یهودیانو به ورڅخه په مذهبي توګه د پاکېدلو د مراسمو د سرته رسولو دپاره کار اخیسته او هر یو یې د اتیاوو څخه تر سلو لیترو پورې ځای درلود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_6.mp3', '', 1761754199, 1761754199),
(34864, 'John 2:7', 'John', 2, 7, 'عیسی نوکرانو ته وویل: «دا منګي د اوبو نه ډک کړئ.» او هغوی هغه منګي تر خولې پورې ډک کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_7.mp3', '', 1761754199, 1761754199),
(34865, 'John 2:8', 'John', 2, 8, 'بیا یې هغوی ته وویل: «اوس د هغو څخه لږ راوباسئ او د مېلمستیا د مراسمو مشر ته یې یوسئ.» نو هغوی همداسې وکړل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_8.mp3', '', 1761754199, 1761754199),
(34866, 'John 2:9', 'John', 2, 9, 'او د مېلمستیا د مراسمو مشر هغه اوبه چې په شرابو باندې بدلې شوې وې، وڅښلې. هغه نه پوهېده چې دا شراب له کومه شول، خو کومو نوکرانو چې دغه اوبه یې راویستلې وې ورڅخه خبر وو، نو د مراسمو مشر زوم راوغوښت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_9.mp3', '', 1761754199, 1761754199),
(34867, 'John 2:10', 'John', 2, 10, 'او ورته ویې ویل: «هرڅوک ښه شراب په پیل کې ورکوي او کله چې مېلمانه نشه شول نو بیا ورته عادي شراب راوړي. خو تا ښه شراب لا تر‌اوسه پورې ساتلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_10.mp3', '', 1761754199, 1761754199),
(34868, 'John 2:11', 'John', 2, 11, 'دا د جلیل په قانا کې د عیسی لومړنۍ معجزه وه چې د هغې په وسیله یې خپله لویي ښکاره کړه او شاګردانو یې ورباندې ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_11.mp3', '', 1761754199, 1761754199),
(34869, 'John 2:12', 'John', 2, 12, 'له هغې وروسته عیسی د خپلې مور، ورونو او خپلو شاګردانو سره کپرناحوم ته لاړ او د یو څو ورځو دپاره هلته پاتې شو. عیسی د خدای کور د پلورونکو نه پاکوي (متي ۲۱‏:‌۱۲‌‏-‌۱۳ او مرقوس ۱۱‏:‌۱۵‌‏-‌۱۷ او لوقا ۱۹‏:‌۴۵‌‏-‌۴۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_12.mp3', '', 1761754199, 1761754199),
(34870, 'John 2:13', 'John', 2, 13, 'د یهودیانو د فسحې اختر رانژدې ؤ، نو عیسی اورشلیم ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_13.mp3', '', 1761754199, 1761754199),
(34871, 'John 2:14', 'John', 2, 14, 'هغه ولیدل چې خلکو د خدای د کور په حوېلۍ کې غویان، پسونه او کوترې خرڅولې او همدارنګه هغه ولیدل چې صرافان د خپلو مېزونو سره ناست وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_14.mp3', '', 1761754199, 1761754199),
(34872, 'John 2:15', 'John', 2, 15, 'هغه یوه رسۍ راواخیستله او دوره یې ترې جوړه کړه او هغوی ټول یې د غویانو او پسونو سره د خدای د کور نه وشړل. د صرافانو مېزونه یې په بل مخ راچپه کړل او د هغوی پیسې یې هرې خواته وشیندلې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_15.mp3', '', 1761754199, 1761754199),
(34873, 'John 2:16', 'John', 2, 16, 'او د کوترو خرڅوونکو ته یې وویل: «دا شیان د دې ځای نه وباسئ! زما د پلار د کور نه بازار مه جوړوئ!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_16.mp3', '', 1761754199, 1761754199),
(34874, 'John 2:17', 'John', 2, 17, 'د هغه شاګردانو ته ور په یاد شول چې د خدای په کلام کې لیکلي شوي دي: «په ما کې چې ستا د کور په خاطر کوم غیرت دی هغه به ما وسوځوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_17.mp3', '', 1761754199, 1761754199),
