(34880, 'John 2:23', 'John', 2, 23, 'کله چې عیسی د فسحې د اختر په وخت کې په اورشلیم کې ؤ نو ډېرو خلکو چې د هغه معجزې ولیدلې په هغه باندې یې ایمان راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_23.mp3', '', 1761754199, 1761754199),
(34881, 'John 2:24', 'John', 2, 24, 'خو عیسی په هغوی باندې اعتبار ونه کړ، ځکه چې هغوی ټول یې ښه پېژندل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john2_verse_24.mp3', '', 1761754199, 1761754199),
