(34891, 'Mark 3:9', 'Mark', 3, 9, 'د خلکو د زیاتې ګڼې‌ګوڼې له امله عیسی خپلو شاګردانو ته وویل چې هغه ته کشتۍ تیاره کړي ترڅو خلک ورباندې زور رانه وړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_9.mp3', '', 1761754199, 1761754199),
(34892, 'Mark 3:10', 'Mark', 3, 10, 'ځکه چې هغه دومره ډېر ناروغان روغ کړي وو چې یو بل یې ټېله کول ترڅو هغه ته لاس وروړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_10.mp3', '', 1761754199, 1761754199),
