(34896, 'Mark 3:14', 'Mark', 3, 14, 'عیسی دولس تنه وټاکل او هغوی یې د رسولانو په نوم یاد کړل چې د هغه سره به اوسي او هغوی به ولېږل شي چې وعظ وکړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_14.mp3', '', 1761754199, 1761754199),
(34897, 'Mark 3:15', 'Mark', 3, 15, 'او دا واک او اختیار به ولري چې پېریان وباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_15.mp3', '', 1761754199, 1761754199),
(34898, 'Mark 3:16', 'Mark', 3, 16, 'هغه دا دولس تنه وټاکل: شمعون چې عیسی ورباندې پطروس نوم کېښود،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_16.mp3', '', 1761754199, 1761754199),
(34899, 'Mark 3:17', 'Mark', 3, 17, 'د زبدي زوی یعقوب او د هغه ورور یوحنا چې په هغوی باندې یې د بوانیرګس نوم کېښود چې معنی یې ده د تندر زامن،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_17.mp3', '', 1761754199, 1761754199),
(34900, 'Mark 3:18', 'Mark', 3, 18, 'او اندریاس، فیلیپوس، بارتولما، متي، توما، د حلفي زوی یعقوب، تدي، شمعون سرتېری،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_18.mp3', '', 1761754199, 1761754199),
(34901, 'Mark 3:19', 'Mark', 3, 19, 'او یهودا اسخریوتي چې د عیسی سره یې خیانت وکړ. عیسی او بعلزبول یعنې شیطان (متي ۱۲‏:‌۲۲‌‏-‌۳۲ او لوقا ۱۱‏:‌۱۴‌‏-‌۲۳، ۱۲‏:‌۱۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_19.mp3', '', 1761754199, 1761754199),
(34902, 'Mark 3:20', 'Mark', 3, 20, 'وروسته عیسی خپل کور ته ننوت او یوځل بیا دومره زیات خلک راټول شول چې عیسی او شاګردانو یې د ډوډۍ خوړلو وخت هم نه درلود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_20.mp3', '', 1761754199, 1761754199),
(34903, 'Mark 3:21', 'Mark', 3, 21, 'کله چې د عیسی خپلوان خبر شول نو، هغوی لاړل چې هغه د ځان سره بوځي، ځکه چې دوی ویل چې هغه لېونی شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_21.mp3', '', 1761754199, 1761754199),
(34904, 'Mark 3:22', 'Mark', 3, 22, 'د شریعت کوم عالمان چې د اورشلیم څخه راغلي وو، ویل یې: «هغه د بعلزبول یعنې د پېریانو د مشر چې شیطان دی، د هغه په مرسته پېریان وباسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_22.mp3', '', 1761754199, 1761754199),
(34905, 'Mark 3:23', 'Mark', 3, 23, 'نو عیسی خلک راوغوښتل او په مثالونو کې یې ورسره خبرې وکړې او ویې ویل: «شیطان څنګه شیطان ویستلی شي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_23.mp3', '', 1761754199, 1761754199),
(34906, 'Mark 3:24', 'Mark', 3, 24, 'که په یوه پاچاهۍ کې بې‌اتفاقي راپیدا شي، نو هغه پاچاهي نه شي پاتې کېدلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_24.mp3', '', 1761754199, 1761754199),
(34907, 'Mark 3:25', 'Mark', 3, 25, 'که په یوه کورنۍ کې بې‌اتفاقي راپیدا شي، نو هغه کورنۍ نوره نه شي پاتې کېدلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_25.mp3', '', 1761754199, 1761754199),
(34908, 'Mark 3:26', 'Mark', 3, 26, 'که چېرې شیطان د خپل ځان په خلاف راپورته شي او د ځان سره بې‌اتفاقه شي، نو هغه نه شي پاتې کېدلی او قدرت یې له منځه ځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_26.mp3', '', 1761754199, 1761754199),
(34909, 'Mark 3:27', 'Mark', 3, 27, 'همدارنګه هېڅوک نه شي کولای چې د یو زورور سړي کور ته ورننوځي او د هغه د کور سامان لوټ کړي، ترڅو چې لومړی هغه سړی وتړي او بیا یې کور لوټ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_27.mp3', '', 1761754199, 1761754199),
(34910, 'Mark 3:28', 'Mark', 3, 28, 'په یقین سره زه تاسو ته دا وایم چې د انسان هر ډول ګناه او حتی هر کفر یې چې ویلی وي هغه به وبخښل شي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_28.mp3', '', 1761754199, 1761754199);